<script setup>
import { onMounted,onUnmounted,ref,computed } from 'vue'; import { api,API_BASE } from '../api'; import { useRouter } from 'vue-router';
const data=ref(null),error=ref(''),router=useRouter(); let socket; async function load(){try{data.value=(await api.get('/dashboard')).data;error.value=''}catch(e){error.value=e.response?.data?.error||'Could not connect to the operations API. Check that the server is running and try again.'}} onMounted(async()=>{await load(); const {io}=await import('../../../../shared/realtime'); socket=io(API_BASE.replace('/api','')); socket.on('simulation-event',load); socket.on('simulation-status',load)}); onUnmounted(()=>socket?.disconnect());
const money=(v,c)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c||data.value?.baseCurrency||'SGD',maximumFractionDigits:0}).format(v||0); const fmt=d=>new Date(d).toLocaleString(undefined,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const metrics=computed(()=>{if(!data.value)return[];const m=data.value.metrics,r=data.value.role;if(r==='OWNER')return [['Sites',m.sites,'Across your portfolio'],['Occupancy',m.occupancy+'%','Portfolio utilisation'],['Monthly NOI',money(m.noi),'Rent + utility margin − OPEX'],['Annual ROI',m.annualRoi+'%',m.expiringLeases+' leases ≤ 90 days']];if(r==='TENANT')return[['SKU lines',m.skuLines,'Across stores + warehouses'],['Low stock',m.lowStock,'Auto-restock candidates'],['Active deliveries',m.activeDeliveries,'Planned + in progress'],['Stores',m.stores,'Retail outlets']];if(r==='DRIVER')return[['Assigned',m.assigned,'Ready for pickup'],['In transit',m.inTransit,'Currently moving'],['Completed',m.completed,'Recorded deliveries'],['Workflow','QR','Scan every handoff']];return[['Open tasks',m.openTasks,'Operational actions'],['Deliveries',m.deliveries,'Across assigned sites'],['Incidents',m.incidents,'Need follow-up'],['Warehouses',m.warehouseCount,'Managed facilities']];});
const advanced=computed(()=>{const k=data.value?.advancedKpis;if(!k)return[];return [['On-time delivery',k.onTimeDeliveryPct+'%','Dispatch service level'],['Inventory accuracy',k.inventoryAccuracyPct+'%','Cycle-count quality'],['Digital traceability',k.digitalTraceabilityPct+'%','QR / RFID / mobile events'],['Space utilisation',k.spaceUtilizationPct+'%','Leased warehouse capacity'],['Dock → dispatch',k.dockToDispatchMinutes+' min','Operational dwell time'],['Order cycle',k.orderCycleHours+' h','Request to fulfil'],['Open incidents',k.openIncidents,'Exception workload'],['POD completion',k.proofOfDeliveryPct+'%','Delivered jobs with evidence']];});
</script>
<template><div v-if="data"><div class="hero"><div><div class="workspace-caption">Your operations, connected</div><h1>{{data.role==='OWNER'?'Portfolio command center':data.role==='TENANT'?'Supply chain workspace':data.role==='DRIVER'?'My delivery run':'Warehouse control desk'}}</h1><p>{{data.role==='OWNER'?'Run a digital warehouse portfolio: leases, ROI, utilities, tenant recovery, warehouse operations, inventory movement and exceptions in one auditable system.':data.role==='TENANT'?'Track stock from warehouse to store, automate replenishment and keep every delivery record traceable.':data.role==='DRIVER'?'Your assigned schedule, pickup/delivery milestones, proof capture and incident reporting in one workflow.':'Manage goods movement, dispatch, exceptions, reconciliation tasks and delivery readiness.'}}</p></div><div class="quick"><button class="btn" @click="router.push('/deliveries')">Open deliveries</button><button v-if="data.role==='OWNER'" class="btn secondary" @click="router.push('/utilities')">Utilities</button><button v-else class="btn secondary" @click="router.push('/scanner')">Scan QR</button></div></div>
<div class="grid4 section"><div class="card metric" v-for="m in metrics" :key="m[0]"><div class="label">{{m[0]}}</div><div class="value">{{m[1]}}</div><div class="sub">{{m[2]}}</div></div></div>
<div v-if="data.role==='OWNER'" class="section"><div class="section-head"><div><h3>Advanced operating KPIs</h3><span>Warehouse digitisation and execution metrics</span></div></div><div class="grid4"><div class="card metric compact" v-for="m in advanced" :key="m[0]"><div class="label">{{m[0]}}</div><div class="value">{{m[1]}}</div><div class="sub">{{m[2]}}</div></div></div></div>
<div v-if="data.role==='OWNER'" class="split section"><div class="card modal-card"><div class="section-head"><div><h3>Utility pulse</h3><span>{{data.utilities.period}} portfolio consumption</span></div><button class="mini-btn" @click="router.push('/utilities')">Open utility intelligence</button></div><div class="utility-pulse"><div><span>Electricity</span><b>{{data.utilities.electricityKwh.toLocaleString()}} kWh</b><small>{{data.utilities.energyChangePct>=0?'+':''}}{{data.utilities.energyChangePct}}% vs prior month</small></div><div><span>Water</span><b>{{data.utilities.waterM3.toLocaleString()}} m³</b><small>{{data.utilities.waterChangePct>=0?'+':''}}{{data.utilities.waterChangePct}}% vs prior month</small></div><div><span>Recovery margin</span><b>{{money(data.utilities.utilityMargin)}}</b><small>{{data.utilities.meterCoveragePct}}% meter coverage</small></div></div></div><div class="card modal-card"><div class="section-head"><div><h3>Digitisation control tower</h3><span>Pen-and-paper replacement coverage</span></div></div><div class="digital-flow"><span>Receive</span><b>→</b><span>Scan</span><b>→</b><span>Put-away</span><b>→</b><span>Pick</span><b>→</b><span>Dispatch</span><b>→</b><span>POD</span></div><p class="note">Every important handoff is designed to create a user, timestamp, location/method and linked document/event record.</p></div></div>
<div class="split section"><div class="card"><div class="section-head" style="padding:16px 16px 0"><h3>{{data.role==='OWNER'?'Live deliveries':data.role==='TENANT'?'Recent deliveries':data.role==='DRIVER'?'My schedule':'Operational deliveries'}}</h3><span>Real-time workflow</span></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Schedule</th><th>Status</th><th>Priority</th></tr></thead><tbody><tr v-for="d in data.deliveries||[]" :key="d.id"><td><b>{{d.id}}</b></td><td>{{fmt(d.scheduledAt)}}</td><td><span class="pill" :class="d.status==='DELIVERED'?'good':d.status==='REASSIGNED'?'warn':''">{{d.status}}</span></td><td>{{d.priority}}</td></tr></tbody></table></div></div><div class="card"><div class="section-head" style="padding:16px 16px 0"><h3>{{data.role==='OWNER'?'Exceptions & alerts':data.role==='TENANT'?'Low stock alerts':data.role==='DRIVER'?'Driver alerts':'Open tasks'}}</h3><span>Action required</span></div><div class="list"><template v-if="data.role==='OWNER'"><div class="list-item" v-for="i in data.incidents" :key="i.id"><span class="dot"></span><div><b>{{i.title}}</b><span>{{i.rectification}}</span></div><span class="pill warn">{{i.severity}}</span></div></template><template v-else-if="data.role==='TENANT'"><div class="list-item" v-for="i in data.lowStock" :key="i.id"><span class="dot"></span><div><b>{{i.name}} · {{i.locationId}}</b><span>{{i.qty}} left / reorder at {{i.reorderPoint}}</span></div><span class="pill bad">LOW</span></div></template><template v-else-if="data.role==='DRIVER'"><div class="list-item" v-for="n in data.notifications" :key="n.id"><span class="dot"></span><div><b>{{n.title}}</b><span>{{n.message}}</span></div></div></template><template v-else><div class="list-item" v-for="t in data.tasks" :key="t.id"><span class="dot"></span><div><b>{{t.title}}</b><span>{{t.type}}</span></div><span class="pill warn">{{t.priority}}</span></div></template></div></div></div></div><div v-else-if="error" class="dashboard-error" role="alert"><b>Dashboard unavailable</b><p>{{error}}</p><button class="btn" @click="load">Try again</button></div><div v-else class="empty">Loading command center…</div></template>
